"""
GameEngine: owns the frog and all vehicles, and runs one frame's worth
of game logic.

Starter version: the frog can move, hop across the road, and reach the
goal - but there's no lives system, no score, and no timer. Collision
detection also has a known bug (see game/collisions.py) that Task 1
asks you to fix.
"""

import random

import pygame

from game.frog import Frog
from game.vehicle import Vehicle
from game.collisions import check_collision
from game.renderer import (
    GRID_COLS, GRID_ROWS, GOAL_ROW, ROAD_ROWS, START_ROW, CELL_SIZE, WIDTH, HEIGHT,
)

LANE_SPEEDS = [1.5, -2, 2, -2.5, 1.5, -2]   # one entry per road row, alternating direction


class GameEngine:
    def __init__(self):
        self._build_entities()

    def _build_entities(self):
        start_col = GRID_COLS // 2
        self.frog = Frog(
            col=start_col, row=START_ROW,
            start_col=start_col, start_row=START_ROW,
            cols=GRID_COLS, start_row_limit=START_ROW,
        )
        frog_x_range = (start_col * CELL_SIZE, start_col * CELL_SIZE + CELL_SIZE)

        self.vehicles = []
        for i, row in enumerate(ROAD_ROWS):
            speed = LANE_SPEEDS[i % len(LANE_SPEEDS)]
            vehicle_width = 40 if i % 2 == 0 else 70   # mix of cars and wider trucks
            spacing = 300
            count = 2

            # Try a few random phases and keep the first one that doesn't
            # already overlap the frog's starting column - guarantees a
            # safe first lane instead of leaving it to chance.
            for _attempt in range(20):
                phase = random.randint(0, spacing - 1)
                positions = []
                safe = True
                for n in range(count):
                    offset = phase + n * spacing
                    x = offset if speed > 0 else WIDTH - offset - vehicle_width
                    positions.append(x)
                    if not (x + vehicle_width <= frog_x_range[0] or x >= frog_x_range[1]):
                        safe = False
                if safe:
                    break

            for x in positions:
                self.vehicles.append(Vehicle(x=x, row=row, width=vehicle_width,
                                              height=CELL_SIZE - 8, speed=speed))

    def handle_keydown(self, key):
        if key == pygame.K_UP:
            self.frog.move(0, -1)
        elif key == pygame.K_DOWN:
            self.frog.move(0, 1)
        elif key == pygame.K_LEFT:
            self.frog.move(-1, 0)
        elif key == pygame.K_RIGHT:
            self.frog.move(1, 0)
        elif key == pygame.K_r:
            self._build_entities()

    def update(self):
        for v in self.vehicles:
            v.update(road_width_px=WIDTH)

        if check_collision(self.frog, self.vehicles):
            self.frog.reset()

        if self.frog.row == GOAL_ROW:
            self.frog.reset()

    def draw(self, surface, font):
        from game import renderer
        renderer.draw_scene(surface, self.frog, self.vehicles)
        renderer.draw_text(surface, font, "Arrow keys to move. R to restart.", (10, HEIGHT - 24))

"""
Frog: the player-controlled character. Moves in discrete grid hops,
one cell per key press - not continuous pixel movement.
"""

import pygame


class Frog:
    def __init__(self, col, row, start_col, start_row, cols, start_row_limit):
        self.col = col
        self.row = row
        self.start_col = start_col
        self.start_row = start_row
        self.cols = cols
        self.start_row_limit = start_row_limit  # frog can't move below its own starting row

    def move(self, dcol, drow):
        new_col = self.col + dcol
        new_row = self.row + drow
        if 0 <= new_col < self.cols:
            self.col = new_col
        if 0 <= new_row <= self.start_row_limit:
            self.row = new_row

    def reset(self):
        self.col = self.start_col
        self.row = self.start_row

    def get_rect(self, cell_size, pad=4):
        return pygame.Rect(
            self.col * cell_size + pad,
            self.row * cell_size + pad,
            cell_size - 2 * pad,
            cell_size - 2 * pad,
        )

"""
Vehicle: a car/truck on a road lane. Moves continuously in pixel space
(not grid-snapped like the frog), wraps around when it exits the screen.
"""

import pygame


class Vehicle:
    def __init__(self, x, row, width, height, speed):
        self.x = float(x)
        self.row = row
        self.width = width
        self.height = height
        self.speed = speed   # px/frame, negative = moving left

    def update(self, road_width_px):
        self.x += self.speed
        if self.speed > 0 and self.x > road_width_px:
            self.x = -self.width
        elif self.speed < 0 and self.x < -self.width:
            self.x = road_width_px

    def get_rect(self, cell_size, pad=4):
        return pygame.Rect(
            int(self.x),
            self.row * cell_size + pad,
            self.width,
            cell_size - 2 * pad,
        )

